use std::fs
use std::env

fn main() {
    let mut number = false
    let mut names: Vec<string> = []
    for a in env::args().skip(1) {
        if a == "-n" { number = true } else { names.push(a) }
    }
    let mut status = 0
    let mut counter = 0
    if names.len() == 0 {
        names.push("/dev/stdin")
    }
    for name in names.iter() {
        match fs::read_to_string(name) {
            Ok(content) => {
                if number {
                    for line in content.lines() {
                        counter += 1
                        println("${counter:>6}\t${line}")
                    }
                } else {
                    print("${content}")
                }
            }
            Err(_) => {
                println("cat: ${name}: No such file")
                status = 1
            }
        }
    }
    if status != 0 {
        std::process::exit(status)
    }
}
